window.GOHUD_SEARCH=window.GOHUD_SEARCH||{};
window.GOHUD_SEARCH["vi"]={"p":["index.html","theming.html","widgets.html"],"n":["Tổng quan","Theme","Widget"],"d":[[0,"showcase","Trông thế nào khi vào game",0,"Preset trung cổ và sci-fi — bảng nhân vật, túi đồ và nhiệm vụ; biểu mẫu, lưới và prompt card; tấm nền góc cạnh và điều khiển cảm ứng. Đổi preset chỉ tốn một dòng code. Trung cổ — nhân vật, túi đồ và nhiệm vụ Trung cổ — biểu mẫu, lưới và prompt card Sci-fi — tấm nền góc cạnh và điều khiển cảm ứng Cả sáu preset và cách chuyển giữa chúng →","",-1],[0,"what","Những việc nó gánh thay bạn",0,"Thứ ngốn nhiều thời gian nhất khi làm UI game không phải hình dáng của một cái nút — mà là tất cả những gì lệch dần giữa các thiết bị. gohud xử lý chỗ lệch đó ở một nơi duy nhất. Mọi số đo đều là một token Khoảng cách, góc bo và cỡ chữ được gọi theo tên chứ không viết thành số. Đổi theme là cả màn hình đổi theo. Cỡ nhìn thấy ≠ cỡ bấm được Nút đóng trông chỉ 36dp nhưng vùng chạm của nó là 48dp. Khi các ô chen nhau và vùng chạm chồng lên nhau, ô nào có tâm gần hơn sẽ nhận cú bấm. Tai thỏ và bàn phím Các mảnh HUD nằm gọn trong vùng an toàn, và ô nhập liệu tự nâng lên trên bàn phím ảo khi bàn phím hiện ra. Back chỉ đóng một thứ Phím Escape và nút Back của Android chỉ đóng lớp trên cùng. Các cửa sổ xếp chồng không biến mất cùng lúc. Thông báo không cướp thao tác Bấm xuyên qua một snackbar thì nút nằm dưới vẫn nhận được. Focus cũng không bị lấy mất. Biểu tượng được gọi theo tên Widget chỉ biết GoIconSet.CLOSE. Đổi bộ biểu tượng là mọi hình vẽ đổi theo mà không phải sửa một dòng code nào. Sáu diện mạo, một dòng GoUi.use_preset() đổi cùng lúc theme, skin và biểu tượng — khung bo tròn, khung vát góc kiểu sci-fi hay khung rèn kiểu trung cổ. Dễ đọc là thứ đo được Mọi theme đều được đối chiếu với WCAG, kể cả các trạng thái của nút và những tấm HUD bán trong suốt đặt trên nền trắng tinh lẫn đen tuyền. Mọi thứ đều chạy mà không cần bật plugin. Bật lên thì có thêm autoload GoRuntime theo dõi kích thước cửa sổ, tỉ lệ dp và chiều cao bàn phím, cùng vài mục project setting cho tài nguyên cấu hình và preset — đó là tiện ích, không phải điều kiện bắt buộc.","",-1],[0,"install","Cài đặt",0,"Đặt thư mục add-on vào dự án. Không phải thiết lập gì thêm.","",-1],[0,"from-the-asset-store-or-a-release-zip","Từ Asset Store hoặc file ZIP bản phát hành",1,"Giải nén vào thư mục gốc của dự án sao cho có res://addons/gohud/. Chỉ vậy thôi. Nếu muốn, hãy bật Project → Project Settings → Plugins → gohud.","",2],[0,"as-a-git-submodule","Dưới dạng git submodule",1,"Thư mục gốc của kho lưu trữ chính là thư mục add-on, nên nó nằm đúng chỗ Godot mong đợi. Sửa ngay tại chỗ, commit và push bên trong addons/gohud, rồi commit con trỏ submodule trong game của bạn. Bắt buộc Godot 4.6 trở lên. gohud dùng các API xuất hiện từ 4.5 (DPITexture, FoldableContainer, các thuộc tính trợ năng), nên trên bản cũ hơn nó lỗi ngay khi phân tích cú pháp. 4.6 là mức thấp nhất được hỗ trợ, ghi trong GoUi.MIN_ENGINE.","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # tùy chọn: ghim vào một tag hoặc commit",2],[0,"start","Bắt đầu nhanh",0,"Mọi widget đều là .new() rồi add_child() — không file scene, không autoload.","",-1],[0,"pick-a-look-before-building-ui-optional","Chọn diện mạo trước khi dựng UI (tùy chọn)",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # bỏ qua dòng này thì default_dark được dùng",5],[0,"a-confirmation-you-await","Một hộp thoại xác nhận mà bạn await",1,"Truyền destructive = true (đối số cuối) thì nút xác nhận được vẽ thành nút nguy hiểm tô đặc.","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Xóa bản lưu\", \"Thao tác này không thể hoàn tác.\"): delete_save()",5],[0,"a-bottom-sheet-with-a-sticky-search-field-and-fo","Bảng trượt dưới với ô tìm kiếm và chân trang cố định",1,"Vì sao hàng cố định tách khỏi phần thân cuộn được. Đặt nút xác nhận và hủy vào body thì một danh sách dài sẽ đẩy chúng ra khỏi màn hình. footer() thì luôn nhìn thấy được.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Túi đồ\") sheet.toolbar().add_child(GoStyle.line_edit(\"Tìm kiếm…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"Đóng\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",5],[0,"a-hud-corner","Một góc HUD",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",5],[0,"content-that-keeps-clear-of-the-hud","Nội dung biết tránh khỏi HUD",1,"Mỗi hình chữ nhật được né theo hướng tốn ít diện tích nhất — xuống dưới trên điện thoại dọc, sang ngang khi nằm ngang. Cách các mảnh HUD tự né nhau →","form.avoid_hud = true # tránh mọi GoHudAnchor đang hiện joystick_anchor.reserve_space = false # …trừ những cái chỉ hiện ra dưới ngón tay notice_anchor.avoid_peers = true # thông báo nổi nằm xuống dưới HUD cố định thay vì che lên nó",5],[0,"presets","Đổi diện mạo — cả màu sắc lẫn hình dáng",0,"Một Theme chỉ đổi được dáng vẻ của những gì engine tự vẽ. StyleBoxFlat chỉ có duy nhất một kiểu góc là bo tròn, còn cần điều khiển, ô nhanh và coach mark thì do code vẽ ra — nên riêng theme không bao giờ đổi được hình dáng của chúng. Vì vậy gohud kèm sẵn preset: một theme, một skin và một bộ biểu tượng chọn thành một khối. Preset Diện mạo default_dark gohud nguyên bản — góc bo tròn, màu nhấn xanh dịu default_light Vẫn hình dáng đó trên bảng màu sáng scifi_dark Góc vát, viền neon lam và ánh sáng tỏa, cần điều khiển hình lục giác, khung ngắm góc scifi_light Vẫn hình dáng góc cạnh đó trong bảng màu bản vẽ kỹ thuật sáng medieval_dark Sắt tối và da thuộc, khung vàng cổ, đinh tán, biểu tượng khắc chìm, tiêu đề Cinzel medieval_light Giấy da, mực và đồng thau với vẫn những khung rèn đó default_dark — góc bo tròn, màu nhấn xanh dịu default_light — cùng hình dáng, bảng màu sáng scifi_dark — góc vát, neon lam scifi_light — cùng hình dáng góc cạnh, bảng màu bản vẽ Bốn ảnh đó là cùng một màn hình gallery. Không khác nhau một dòng code nào — chỉ khác tên preset. Góc nút, hình công tắc, hàng danh sách và viền ô nhập đều đổi theo cùng lúc.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # theme, skin và biểu tượng cùng lúc",-1],[0,"medieval-collection","Bộ sưu tập trung cổ",1,"medieval_dark ghép sắt và da thuộc với vàng cổ; medieval_light dùng giấy da và mực. Khung menu mang một chiếc đinh tán và một hoa văn góc nhỏ, còn HUD luôn hiện thì giữ nét trầm; 16 biểu tượng khắc chìm vẽ lại các món đồ, và chỉ tiêu đề với phụ đề mới dùng font Cinzel kèm theo. medieval_dark — sắt và da thuộc medieval_light — giấy da và mực Cả hai ảnh đều là examples/medieval/medieval.tscn, dựng từ các widget tiêu chuẩn. Hướng dẫn trung cổ và cách tạo vương quốc của riêng bạn →","",11],[0,"the-same-screen-on-a-phone-and-on-a-desktop","Cùng một màn hình trên điện thoại và trên máy để bàn",1,"Các ảnh gallery là điện thoại ở chế độ dọc. Bên dưới là cùng đoạn code đó ở 1280×800 — nội dung dừng lại ở bề ngang dễ đọc (480dp) rồi canh giữa, còn HUD vẫn nằm ở các góc. Biểu mẫu bước tránh các mảnh HUD nổi, nhưng không nhúc nhích khi nó vốn đã không vướng: cứ đẩy bừa thì trên màn hình rộng nội dung sẽ lệch khỏi tâm. default_dark · 1280×800 scifi_dark · 1280×800","",11],[0,"the-same-sheet-a-different-look","Cùng một bảng trượt, khác diện mạo",1,"Mặc định — thẻ bo tròn, hàng tìm kiếm và chân trang cố định Sci-fi — viền nhấn ở mép trên, góc cắt, ánh sáng tỏa Chọn một preset trong Project Settings → gohud → Theme → Preset, hoặc đặt GoConfig.preset. Điền thẳng theme, skin hay icons thì giá trị đó thắng preset, nên bạn có thể lấy một preset rồi ghi đè đúng một phần của nó. Một theme mới chỉ là một file JSON. new_theme.py kingdom --from medieval_dark ghi ra một bảng màu liệt kê rõ từng giá trị kế thừa; make_theme.py kingdom dựng theme, phần hình vẽ cho các control và các núm chỉnh của skin, rồi preset hiện ra trong danh sách chọn. Mọi thiết lập và núm chỉnh →","",11],[0,"skin","Skin — nơi Theme không với tới",0,"Skin nắm cần điều khiển, mặt các ô nhanh, vòng coach mark, chip, skeleton, alert, đường kẻ chia và tiêu đề mục. Kế thừa nó rồi chỉ ghi đè đúng phần bạn muốn đổi. Lớp Hình dáng nó tạo ra được GoStyleBoxCut Góc cắt chéo (vát), một cạnh nhấn dày lên, ánh sáng tỏa ra ngoài GoStyleBoxBracket Chỉ dấu ở bốn góc, không bao kín nội dung GoStyleBoxMedieval Khung rèn với đinh tán, hoa văn khắc ở góc, vệt sáng vát cạnh và vân vật liệu Cả ba đều tuần tự hóa được vào một tài nguyên Theme — chính điều đó cho phép một theme đổi hình dáng, chứ không chỉ đổi màu. GoSkinSciFi và GoSkinMedieval là hai lớp con có sẵn. GoStyle.box() luôn trả về một StyleBoxFlat, vì phía gọi nhận nó rồi chỉnh bg_color hoặc corner_radius. Hãy dùng GoStyle.surface() khi cần giữ nguyên một hình dáng tùy biến.","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","Widget",0,"Toàn bộ các mảnh, gói trong một bảng. Chi tiết từng cái → Lớp Lớp cha Làm gì GoSurface Control Vỏ thẻ nổi — đặt ở giữa, ở đáy hoặc neo vào một control, đầu và chân trang cố định, thân cuộn được, kéo để đổi kích thước GoSheet CanvasLayer Trang trồi lên từ đáy, nằm trên lớp riêng nên luôn ở trên HUD GoDialogs Node Hộp thoại xác nhận và cảnh báo mà bạn await; destructive cho các thao tác không thể hoàn tác GoForm MarginContainer Biểu mẫu giới hạn bề ngang, tránh bàn phím ảo và, với avoid_hud, tránh cả HUD GoScroll ScrollContainer Cuộn bằng ngón tay; thanh cuộn nép vào phần đệm sẵn có của thẻ GoNotice PanelContainer Snackbar không nhận thao tác cũng không nhận focus GoPromptCard PanelContainer Một câu hỏi không chặn game lại GoCoachMark Control Chuyến tham quan có hướng dẫn chỉ vào các control thật; bấm đúng mục tiêu là sang bước kế GoHudAnchor Control Ghim các mảnh HUD vào một trong chín vị trí trong vùng an toàn GoBar Control Thanh máu, mana và kinh nghiệm với chuyển động mượt GoSlot Button Một ô nhanh — biểu tượng, số lượng, hồi chiêu và phím tắt trên cùng một mặt GoJoystick Control Cần điều khiển ảo ở chế độ cố định, đi theo hoặc tương đối GoIconButton Button Trông nhỏ, bấm rộng GoStyle static Nút, hàng danh sách, ô nhập, chip, bảng, tab và nhiều thứ khác, làm ra theo một cách thống nhất","",-1],[0,"examples","Những ví dụ chạy được ngay",0,"Ba cách xem gohud trước khi viết dòng nào — không cách nào cần server hay autoload. Ví dụ Cách mở Cho thấy gì Gallery examples/gallery/gallery.tscn · F6 Mọi widget, một danh sách chọn cho từng preset đã cài, và trọn bộ biểu tượng Trung cổ examples/medieval/medieval.tscn · F6 Bảng nhân vật, túi đồ và sổ nhiệm vụ; các nút chuyển giữa sắt và giấy da rồi mở chi tiết món đồ Ứng dụng demo cd examples/demo && godot Một màn hình chính mở ra gallery, chuyến tham quan 15 chương, màn hình trưng bày và diện mạo trung cổ, với widget chạy thật và mỗi lớp một tấm thẻ Ứng dụng demo không cần thiết lập gì: nếu thiếu liên kết tới add-on hay bộ nhớ đệm import, nó sẽ báo, sửa lại thư mục rồi tự mở lại. Màn hình chính của nó mở từng ví dụ ngay trong cùng một cửa sổ — nhấn 1–4 hoặc bấm vào một hàng, còn thanh chạy ngang phía trên đưa bạn quay lại. Trong chuyến tham quan, C bật tắt chế độ Cinema, F11 toàn màn hình, Space tạm dừng (hoặc chạy widget hiện tại khi đang khám phá), các phím mũi tên đổi chương và Escape quay về màn hình đầu. Đang dùng một AI coding agent? Mở cả ba bằng một lệnh →","cd examples/demo && godot # màn hình chính; lần chạy đầu sẽ tạo liên kết và import bash examples/demo/run.sh # vẫn ứng dụng đó, chạy từ thư mục gốc của add-on bash examples/demo/run.sh -- --open=gallery # bỏ qua màn hình chính bash examples/demo/run.sh -- --explore=surfaces # mở thẳng vào một chương của chuyến tham quan bash examples/demo/run.sh --record /tmp/gohud-demo.avi # quay chuyến tham quan ở 1080p / 60 fps",-1],[0,"ai","Mở nó từ AI coding agent của bạn",0,"gohud kèm theo một plugin cho Claude Code với các lệnh gạch chéo. Gõ một lệnh là gallery hoặc bản demo mở ra trong cửa sổ Godot riêng của nó — không phải khởi động trình soạn thảo, không phải đi tìm scene.","",-1],[0,"install-the-commands-once","Cài các lệnh một lần",1,"Các agent khác như Codex dùng được đúng skill đó: chép skills/gohud từ kho này vào thư mục skill của agent.","claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud # rồi khởi động lại Claude Code",18],[0,"gohud-preview-the-widget-gallery","/gohud:preview — gallery widget",1,"Mở gallery: mọi widget, một danh sách chọn cho cả sáu preset và trọn bộ biểu tượng. Gõ lệnh này bên trong dự án Godot của bạn thì nó dùng addons/gohud của bạn; không có thì nó dùng bản kèm theo plugin, hoặc clone mới một bản. Nó chạy trong một dự án sandbox dùng xong bỏ, nên autoload và bộ nhớ đệm import của bạn không bị đụng tới, còn cửa sổ thì mở cho đến khi bạn đóng.","",18],[0,"gohud-preview-demo-the-15-chapter-guided-tour","/gohud:preview demo — chuyến tham quan 15 chương",1,"Mở bản demo ở màn hình đầu. Bắt đầu demo chạy chuyến tham quan bằng thao tác thật; Khám phá widget cho bạn tự thử từng widget. Các phím liệt kê ở mục Ví dụ cũng dùng được ở đây.","",18],[0,"many-other-commands","Nhiều lệnh khác",1,"Lệnh Làm gì /gohud:preview medieval Bảng nhân vật, túi đồ và sổ nhiệm vụ trong các preset trung cổ /gohud:preview demo --explore hud Bản demo mở thẳng vào một chương — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark Gallery trong một preset; thêm --phone để có cửa sổ điện thoại 390×844 hoặc --size 1920x1080 cho kích thước bất kỳ /gohud:preview res://ui/main_menu.tscn Một scene trong dự án của bạn, chạy ngay bên trong dự án đó /gohud:preview list Mọi mục tiêu, id preset và khóa chương demo /gohud:preview gallery --check Một lượt kiểm tra nhanh không cửa sổ — sẽ báo lỗi nếu script có lỗi /gohud:features Mọi tính năng, xếp theo nhóm, mỗi cái một dòng code /gohud:features hud Một mảng đi sâu — surfaces hud style theming icons i18n accessibility config Hoặc cứ hỏi thẳng. Skill này dạy cho agent toàn bộ API của gohud, nên yêu cầu bằng lời bình thường cũng chạy — \"Dựng giúp tôi một menu tạm dừng bằng gohud\". Nếu cài như một skill thường ở ~/.claude/skills/gohud, các lệnh viết cách ra một khoảng trắng: /gohud preview demo, /gohud features. Xem trước cần Godot 4.6 trở lên nằm trong PATH, hoặc truyền --godot /path/to/godot.","",18],[0,"readable","Dễ đọc là đo được, không phải ước lượng bằng mắt",0,"\"Đẹp\" là chuyện gu; \"dễ đọc\" thì đo được. Chữ xám nhạt trông ổn trên màn hình tốt và biến mất trên điện thoại giữa ban ngày — chọn bằng mắt thì sớm muộn cũng dính. Mọi cặp màu và nhãn của từng trạng thái nút trên chính tấm nền nó nằm lên đều được đo theo WCAG, trên cả sáu theme. Màu bán trong suốt được ghép lên nền thật của nó trước — đo thẳng vào chúng sẽ cho tỉ số đẹp hơn những gì màn hình thật sự hiển thị. Vì vậy màu chữ là thứ suy ra, không phải chọn: trình dựng lấy màu trong bảng màu làm điểm xuất phát rồi đẩy độ sáng của nó lên cho tới khi vượt ngưỡng trên mọi bề mặt mà nó có thể rơi vào. Đổi bảng màu thì độ tương phản đi theo. Các quy tắc và những cái bẫy phía sau chúng →","python3 addons/gohud/tools/check_contrast.py",-1],[0,"develop","Kiểm tra, phát hành và trang web này",0,"Một điểm vào chạy mọi lượt kiểm tra; mỗi phần thấy được thứ mà các phần kia không thấy. Lượt kiểm tra Bắt được gì run_tests.sh ở bốn cỡ màn hình Hành vi và bố cục widget, vị trí khi RTL, focus bàn phím, độ tương phản của skin lúc chạy, mọi preset new_project_check.sh Những phụ thuộc ngầm vào dự án chủ; với --zip là bản phát hành đúng như khi giao, với --export là một bản build Web check_contrast.py Độ tương phản WCAG của từng file theme, tính cả trạng thái nút và tấm nền bán trong suốt check_generated.py · check_scaffold.sh Theme sinh ra khớp với bảng màu của nó; một theme dùng xong bỏ dựng được và qua được kiểm tra tương phản check_package.py Việc tăng số phiên bản, chuyển mục changelog và nội dung file ZIP, trên các bản sao tạm check_site.py Liên kết, neo, ngôn ngữ trang, bảng thuật ngữ và bảng núm chỉnh của trang này Lượt chạy gần nhất được ghi lại — 2026-09-13, Godot 4.7.2, macOS, renderer Compatibility. 438 trên 438 lượt kiểm tra ở 390×844, 844×390, 768×1024 và 1280×800 trong một dự án trống; lại 438 trên 438 khi có autoload GoRuntime; một bản export Web; không một lỗi tương phản nào trên cả sáu theme. Godot 4.6 và thiết bị Android hay iOS thật không nằm trong lượt chạy này.","bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","Phiên bản phát hành",1,"Một lượt chạy thành công cập nhật plugin.cfg, GoUi.VERSION và CHANGELOG.md cùng lúc, chuyển phần ghi chú Unreleased thành một mục có ngày tháng. Lượt chạy hỏng thì không đổi gì cả, và một file ZIP đã có sẽ không bao giờ bị ghi đè. File ZIP không chứa trang web này, phần kiểm thử và các công cụ.","bash addons/gohud/tools/package.sh # 1.0.1 → 1.0.2 · builds/1.0.2/gohud-1.0.2.zip bash addons/gohud/tools/package.sh --increase-minor-version # 1.0.1 → 1.1.0",24],[0,"this-site","Trang web này",1,"Các trang là HTML thuần trong www/ — tiếng Anh ở thư mục gốc, tiếng Hàn trong ko/. Một workflow GitHub Actions xuất bản thư mục đó làm gốc của trang web.","python3 addons/gohud/tools/make_site.py # bảng thuật ngữ và bảng núm chỉnh của skin, sinh ra từ mã nguồn python3 addons/gohud/tools/check_site.py # liên kết, neo, ngôn ngữ, bảng thuật ngữ, bảng được sinh ra bash addons/gohud/tools/site_shots.sh /tmp/shots # ảnh chụp mọi trang ở cỡ máy để bàn và điện thoại",24],[1,"layers","Ba lớp",0,"Một preset gói cả ba. Những trường bạn để trống sẽ lùi về giá trị mặc định. Lớp Quyết định Cách đổi Theme Màu sắc, kích thước, tỉ lệ chữ, và hình dáng của mọi thứ do engine vẽ — tấm nền của nút, ô nhập, tab, hình vẽ công tắc Tự soạn một file .tres, hoặc sinh ra bằng tools/make_theme.py GoSkin Hình dáng của mọi thứ do code vẽ — cần điều khiển, mặt các ô nhanh, vòng coach mark, chip, skeleton, đường kẻ chia, tiêu đề mục Kế thừa nó rồi chỉ ghi đè những phương thức bạn quan tâm GoIconSet Biểu tượng gọi theo tên — 84 hình mặc định, hoặc 16 hình khắc chìm của bộ trung cổ phủ lên chúng. Một gói texture hay một font biểu tượng; phía gọi viết y như nhau Cung cấp một bộ, hoặc chỉ ghi đè vài cái tên Vì sao chỉ một Theme là chưa đủ. Bo tròn là kiểu góc duy nhất mà StyleBoxFlat có — đặt bán kính về không thì được góc vuông; giữa hai thứ đó không có gì cả. Góc cắt chéo, một cạnh dày lên, ánh sáng tỏa ra ngoài: engine không vẽ cái nào trong số đó. Còn cần điều khiển và coach mark thì được vẽ trong _draw(), nơi theme hoàn toàn không với tới.","",-1],[1,"pick","Chọn một cái",0,"Đúng một dòng đó đổi cả theme, skin và biểu tượng. Từ trình soạn thảo thì dùng Project Settings → Gohud → Theme → Preset; từ một tài nguyên cấu hình thì dùng GoConfig.preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[1,"keeping-one-field-your-own","Giữ riêng một trường cho mình",1,"Đặt thẳng theme, skin hay icons thì giá trị đó thắng preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # biểu tượng của bạn, còn lại là của preset",28],[1,"the-six-built-in-presets","Sáu preset có sẵn",1,"Preset Tấm nền Skin · biểu tượng default_dark · default_light Tấm nền StyleBoxFlat bo tròn trên một thang đổ bóng chia bậc; nút chính nhô lên rồi lún xuống khi bấm GoSkin · 84 biểu tượng mặc định scifi_dark · scifi_light Tấm nền GoStyleBoxCut vát góc với viền neon và ánh sáng tỏa; dấu focus bằng GoStyleBoxBracket GoSkinSciFi — cần điều khiển hình lục giác · biểu tượng mặc định medieval_dark · medieval_light Khung rèn GoStyleBoxMedieval — sắt và da thuộc, hoặc giấy da — với đinh tán và hoa văn góc trên các menu GoSkinMedieval · 16 biểu tượng khắc chìm phủ lên bộ mặc định","",28],[1,"medieval","Trung cổ: sắt, da thuộc và giấy da",0,"medieval_dark ghép sắt tối và da thuộc với vàng cổ. medieval_light dùng giấy da và mực. Cả hai đều dùng GoSkinMedieval, vẫn các widget sẵn có, và 16 biểu tượng nguyên bản với chi tiết khắc chìm; biểu tượng điều hướng lùi về bộ gốc. Hãy chọn preset trước khi tạo UI. Giá trị đặt thẳng cho GoConfig.theme, skin hay icons vẫn được ưu tiên. Mở res://addons/gohud/examples/medieval/medieval.tscn rồi nhấn F6 để xem một bảng nhân vật, túi đồ và sổ nhiệm vụ chạy thật. Các nút trong đó chuyển biến thể và mở chi tiết món đồ. Sắt và da thuộc Giấy da và mực Khung menu có một chiếc đinh tán và hoa văn góc nhỏ; HUD luôn hiện thì giữ nét viền trầm. Máu, mana và thể lực dùng phần tô màu đỏ, lam và ô liu. Cinzel chỉ dùng cho tiêu đề và phụ đề; chữ thân bài giữ font của dự án chủ hoặc font mặc định. Font kèm theo có sẵn giấy phép của nó tại assets/fonts/cinzel/OFL.txt. Bộ khắc chìm vẽ lại bag, book, box, coin, crown, flag, heart, key, map, potion, shield, star, sword và user, đồng thời thêm scroll và seal. Mọi cái tên khác lùi về bộ mặc định, nên close và settings giữ nguyên hình vẽ mặc định ở mọi preset. Cinzel chỉ phủ chữ Latinh; hãy cấp cho tiêu đề đã bản địa hóa một font riêng qua shape.fonts. Bộ kiểm thử xét gì cho cả hai biến thể. Skin trung cổ được chọn đúng; tấm nền menu và HUD là khung rèn, còn hoa văn thì chỉ xuất hiện trên menu; tiêu đề dùng Cinzel trong khi chữ thân bài giữ font kế thừa; biểu tượng khắc chìm được import thành DPITexture; một ô nhanh thật dùng đúng skin; đổi núm chỉnh của một bản sao skin thì thay đổi lan tới ô nhanh mà không phải đụng vào preset; và chuyển ngược lại thì hình dáng của bản mặc định lẫn sci-fi được khôi phục.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # Hoặc: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[1,"make-a-kingdom-of-your-own","Dựng một vương quốc của riêng bạn",1,"Theme JSON kế thừa được theme JSON khác. Giá trị bỏ trống thì giữ thiết lập của theme cha; kế thừa vòng tròn sẽ bị từ chối. Preset sinh ra giữ lại bộ biểu tượng của theme cha. Thiết lập Tác dụng shape.material 0: sắt · 1: da thuộc · 2: giấy da. Quyết định các vết trên bề mặt. shape.grain_alpha Độ đậm của vân bề mặt. Đặt 0 để có mặt phẳng sạch. shape.ornament_scale · shape.bevel_strength Cỡ hoa văn ở góc menu và độ mạnh của vệt sáng vát cạnh. shape.fonts Gán các vai trò tiêu đề, phụ đề, chú thích, thân bài và nút vào các file font res:// nằm trong add-on. Vai trò bỏ trống thì giữ font kế thừa. skin.dials Bán kính góc ô nhanh, đinh tán hiện hay ẩn, vân và vệt sáng. Bảng đầy đủ bên dưới liệt kê từng núm chỉnh.","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # Sửa themes/palettes/kingdom.json, rồi: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # Trong GDScript, trước khi tạo các widget: GoUi.use_preset(&\"kingdom\")",31],[1,"tokens","Token",0,"Mọi màu sắc và số đo đều nằm dưới kiểu GoHud trong Theme và được gọi theo tên. Không viết số là quy tắc: đổi theme thì cái tên đi theo.","GoUi.color(GoTheme.ACCENT) # màu GoUi.metric(GoTheme.GAP) # số đo (dp) GoUi.font_size(GoTheme.ROLE_CAPTION) # cỡ chữ cho một vai trò văn bản GoUi.box(GoTheme.BOX_CARD) # một bản sao của StyleBox",-1],[1,"colours","Màu sắc",1,"Tên Dùng cho background Nền dưới cùng của màn hình surface · surface_soft · surface_high Ba lớp tấm nền — tấm nền, thẻ, ô nổi lên border Viền của thẻ và nút text · secondary · muted Ba mức chữ — thân bài, phụ trợ, mờ nhạt accent · on_accent Màu nhấn và màu chữ đặt lên nó success · warning · danger · info Màu chữ cho các trạng thái *_fill Vẫn các trạng thái đó nhưng dùng làm phần tô — thanh và các mảng lớn khác scrim · shadow · track Lớp phủ mờ sau popup, bóng đổ, rãnh của thanh Vì sao có *_fill. Cùng một ý nghĩa nhưng yêu cầu ngược nhau. warning dùng làm chữ thì phải đủ tối để đọc được trên nền sáng; dùng làm phần tô của thanh kinh nghiệm thì phải đủ sáng để gây chú ý. Một token không thể vừa thế này vừa thế kia — thanh của theme sáng đã ngả thành nâu. Theme nào không có biến thể _fill thì tự động lùi về cái tên gốc, nên những theme có trước các token này vẫn chạy bình thường.","",33],[1,"measurements-dp","Số đo (dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",33],[1,"text-roles","Vai trò văn bản",1,"micro · compact · caption · body · button · subtitle · title — một vai trò đặt tên cho một cỡ chữ, không phải cho một mục đích. \"Chữ lớn nhất\", chứ không phải \"tiêu đề\". Nhờ vậy thang cỡ chữ vẫn đứng vững ngay cả khi một màn hình dùng nó cho việc khác.","",33],[1,"type-variations","Biến thể kiểu",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",33],[1,"skin","Skin — nơi Theme không với tới",0,"Phương thức Quyết định surface_box · floating_box · overlay_box Mặt của thẻ và tấm nền, các lớp nổi, những viên thuốc đặt chồng lên game hay bản đồ chip_box · chip_ink Tấm nền của một chip và màu nhãn vẫn đọc được trên nó slot_box · slot_ink Mặt của các ô nhanh và chữ trên đó disc_box Vòng tròn phía sau ảnh đại diện hay badge alert_box · skeleton_box · segment_box Alert nội dòng, khối giữ chỗ, control chia đoạn coach_ring_box Dấu mà chuyến tham quan vẽ quanh mục tiêu của nó draw_joystick · draw_coach_pointer Những thứ vẽ trực tiếp — cần điều khiển và mũi chỉ của nó divider_color · divider_thickness · section_box Đường kẻ chia và tiêu đề mục badge_box Badge trên ô nhanh — số lượng và thời gian còn lại progress_fill_box · notice_box · tint_notice Phần tô của thanh (có viền khi phần tô không đạt nổi 3:1 so với rãnh của nó) và snackbar","class_name MySkin extends GoSkin func draw_joystick(canvas: CanvasItem, center: Vector2, knob: Vector2, radius: float, knob_radius: float, ink: Color, base: Color, active: bool) -> void: # Widget đã tính sẵn các vị trí — ở đây chỉ còn việc vẽ canvas.draw_circle(center, radius, Color(base, 0.4)) canvas.draw_circle(knob, knob_radius, ink)",-1],[1,"shapes-styleboxflat-cannot-make","Những hình dáng StyleBoxFlat không tạo được",1,"Lớp Vẽ ra gì GoStyleBoxCut Góc cắt chéo, một cạnh nhấn dày lên, ánh sáng tỏa ra ngoài GoStyleBoxBracket Chỉ dấu ở bốn góc, để nội dung không bị bao kín GoStyleBoxMedieval Khung rèn — đinh tán, hoa văn khắc ở góc, vệt sáng vát cạnh và vân sắt, da thuộc hay giấy da Cả ba đều tuần tự hóa được vào một tài nguyên Theme như mọi StyleBox khác — chính điều đó cho phép một theme đổi hình dáng. Hãy cấp phần đệm qua content_margin_*. Kế thừa StyleBox trong GDScript nghĩa là _get_style_margin() không bao giờ được gọi (đo trên Godot 4.7). Hãy điền các trường có sẵn, nếu không nội dung sẽ dính sát vào viền.","",38],[1,"own","Preset của riêng bạn — một file",0,"Thêm một theme trước đây có nghĩa là sửa tay bốn chỗ — bảng màu của trình dựng, phần hình dáng, một skin, một tài nguyên preset. Giờ một lệnh đặt tất cả vào đúng chỗ. Dòng đầu ghi ra themes/palettes/neon.json và themes/presets/neon.tres. File JSON mang theo mọi giá trị của theme mà nó kế thừa, viết ra đầy đủ, nên nó kiêm luôn bản liệt kê những gì bạn đổi được: xóa một khóa để giữ giá trị của theme cha, viết một khóa để ghi đè. Preset được tìm bằng cách quét themes/presets/, nên không phải sửa code đăng ký nào cả — danh sách thả xuống trong project setting cũng tự thấy nó.","python3 addons/gohud/tools/new_theme.py neon --from scifi_dark --title \"Neon\" python3 addons/gohud/tools/make_theme.py neon # file .tres của theme + hình vẽ cho các control godot --headless --path . --import # import phần hình vẽ mới một lần GoUi.use_preset(&\"neon\") # xong — nó cũng hiện ra trong danh sách chọn",-1],[1,"what-you-can-change-on-one-page","Những gì bạn đổi được — gói trong một trang",1,"Ở đâu Cái gì Bằng cách nào from theme cha dark · light · scifi_dark · medieval_dark · … hoặc một theme JSON khác. Khóa bỏ trống thì kế thừa giá trị của nó; kế thừa thành vòng tròn sẽ báo lỗi palette nền · ba lớp bề mặt · viền · ba sắc độ chữ · màu nhấn · bốn màu trạng thái · lớp phủ mờ · bóng đổ · rãnh thanh \"#RRGGBB\", alpha viết là \"#RRGGBB@0.35\" màu rực chỉ dùng để tô *_vivid giữ cho thanh luôn tươi ngay cả khi màu chữ buộc phải tối đi — bỏ sót một cái thì trình dựng sẽ báo độ dễ đọc không chỉnh bằng tay. Chữ, viền, màu nhấn và nhãn nằm trên nó đều được trình dựng đẩy cho tới khi vượt ngưỡng — chỉ đổi mỗi màu nhấn thì các lượt kiểm tra vẫn qua shape kind flat (bo tròn) · cut (góc vát) · medieval (khung rèn) kích thước radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — các token đi theo, nên tấm nền và phần tính toán của widget không bao giờ lệch nhau chỉ với cut cut_ratio · cut_max · corners (diagonal|all) · glow · edge chỉ với medieval material (0 sắt · 1 da thuộc · 2 giấy da) · grain_alpha · ornament_scale · bevel_strength · fonts — title, subtitle, caption, body, button gán vào các file font res:// nằm trong add-on skin base — dòng skin cho những chỗ code tự vẽ lấy (cần điều khiển, ô nhanh, badge, vòng coach mark, chip, đường kẻ chia) default · scifi · medieval dials — các con số của những chỗ đó: bề rộng và sắc pha của viền ô nhanh, phần đệm của badge, độ đậm của chip và alert, bề rộng và độ đậm của vòng cần điều khiển, cỡ vát góc, ánh sáng tỏa và dấu góc của sci-fi Mọi giá trị của theme cha đều được viết rõ trong file JSON. Trình dựng ghi chúng vào themes/skins/gohud_skin_<id>.tres — không đụng tới code skin nào. Chỉ khi muốn đổi chính hình vẽ bạn mới chạy --new-skin, lệnh này dựng khung sẵn cho một lớp con của GoSkin icons bộ biểu tượng một đường dẫn res:// tới tài nguyên GoIconSet — bỏ trống thì giữ lại của theme JSON cha dark · title cách danh sách chọn hiển thị nó boolean · chuỗi","",40],[1,"every-dial","Toàn bộ núm chỉnh",1,"Bảng dưới đây do tools/make_site.py điền thẳng từ các dòng @export trong script của skin — thêm một núm chỉnh hay đổi một giá trị mặc định thì bảng đi theo. Hãy dùng đúng những cái tên này dưới skin.dials trong file JSON. Núm chỉnh có mặc định ghi là 14 là số nguyên, cái ghi 10.0 là số thực — viết kiểu nào trong JSON cũng được, trình dựng sẽ ép về đúng kiểu của script. Skin mặc định GoSkin — 17 Núm chỉnh Mặc định Đặt cái gì chip_fill_alpha 0.16 Độ đậm phần tô trên tấm nền của một chip. chip_edge_alpha 0.45 Độ đậm phần viền trên tấm nền của một chip. alert_tint 0.1 Tấm nền của hộp alert ngả về màu trạng thái của nó bao nhiêu. slot_tint_lit 0.24 Mức pha màu nhấn vào tấm nền của ô nhanh khi hồi chiêu đang chạy. slot_tint_idle 0.08 Mức pha màu nhấn vào tấm nền của ô nhanh lúc bình thường. slot_border_lit 2 Bề rộng viền ô nhanh (dp) khi hồi chiêu đang chạy. slot_border_idle 1 Bề rộng viền ô nhanh (dp) lúc bình thường. badge_pad_x 5 Phần đệm ngang bên trong (dp) của một badge (số lượng, thời gian còn lại). badge_pad_y 1 Phần đệm dọc bên trong (dp) của một badge. badge_edge_alpha 0.6 Độ đậm phần viền trên tấm nền của một badge. float_shadow_alpha 0.45 Độ đậm bóng đổ của các thẻ nổi (coach mark, prompt card). float_shadow_size 14 Độ nhòe (dp) của bóng đổ trên thẻ nổi. float_shadow_lift 4 Khoảng lệch xuống dưới (dp) của bóng đổ trên thẻ nổi. float_glow_size 10.0 Khoảng tỏa sáng (dp) của tấm nền nổi dùng ánh sáng thay cho bóng đổ, như tấm nền vát góc kiểu sci-fi. joystick_base_alpha 0.42 Độ đậm của đĩa nền dưới cần điều khiển. joystick_ring_alpha 0.45 Độ đậm của vòng quanh cần điều khiển. joystick_ring_width 2.0 Bề rộng (dp) của vòng quanh cần điều khiển. Skin sci-fi GoSkinSciFi — 10 Núm chỉnh Mặc định Đặt cái gì cut_chip 7.0 Cỡ vát góc (dp) trên tấm nền của một chip. cut_skeleton 5.0 Cỡ vát góc (dp) của một tấm nền skeleton. cut_alert 8.0 Cỡ vát góc (dp) của một hộp alert. cut_segment 8.0 Cỡ vát góc (dp) của một control chia đoạn. cut_slot 6.0 Cỡ vát góc (dp) trên tấm nền của một ô nhanh. cut_disc_ratio 0.24 Vát góc của ảnh đại diện và đĩa tròn = đường kính × tỉ lệ này. slot_glow_alpha 0.45 Độ đậm ánh sáng tỏa của một ô đang hồi chiêu. slot_glow_size 6.0 Khoảng tỏa sáng (dp) của một ô đang hồi chiêu. bracket_arm 12.0 Chiều dài nhánh (dp) của khung ngắm góc trên coach mark. bracket_thickness 2.0 Độ dày nét (dp) của khung ngắm góc trên coach mark. Skin trung cổ GoSkinMedieval — 5 Núm chỉnh Mặc định Đặt cái gì slot_radius 4.0 Bán kính bo góc (dp) của khung ô nhanh kiểu trung cổ. leather_grain_alpha 0.035 Độ đậm của những vết da thuộc mờ bên trong các ô nhanh. ornament_scale 1.0 Tỉ lệ của các chi tiết kim loại ở góc ô nhanh. Khung menu dùng shape.ornament_scale. bevel_strength 0.18 Độ mạnh của vệt sáng kim loại dọc theo mép ô nhanh. slot_rivets 1 Hiện những chiếc đinh tán kim loại nhỏ trên ô nhanh: 0 là ẩn, 1 là hiện.","",40],[1,"subclass-the-skin-optional","Kế thừa skin (tùy chọn)",1,"Chỉ những gì theme và hình dáng không với tới — hình lục giác của cần điều khiển, badge trên ô nhanh, khung ngắm góc của coach mark — mới nằm trong một skin. Hãy kế thừa GoSkin, chỉ ghi đè đúng các phương thức đó, rồi trỏ trường skin trong file JSON vào tài nguyên đó. Một theme chỉ đổi màu thì bỏ qua bước này. Một lượt kiểm tra giữ đúng lời hứa. tools/check_scaffold.sh tạo một theme dùng xong bỏ ở mỗi lần chạy — đổi màu nhấn, đặt bán kính bằng 4 — rồi xác minh việc sinh ra, việc token lan truyền và một lượt kiểm tra tương phản sạch sẽ trước khi xóa nó đi. Lần chạy đầu tiên đã phát hiện một theme chỉ đổi mỗi màu nhấn mà hỏng mất 8 cặp màu: trình dựng đẩy màu chữ nhưng lại dùng màu nhấn đúng như được viết. Giờ nó đẩy cả màu nhấn lẫn nhãn nằm trên đó.","",40],[1,"contrast","Dễ đọc là thứ đo được",0,"\"Đẹp\" là chuyện gu; \"dễ đọc\" thì đo được. Chữ xám nhạt trông ổn trên màn hình tốt và biến mất trên điện thoại giữa ban ngày — chọn bằng mắt thì sớm muộn cũng dính. Cái gì Mức yêu cầu Chữ thân bài 4.5 : 1 Chữ lớn (từ 24px trở lên) 3 : 1 Viền và biểu tượng màu nhấn 3 : 1 Viền trang trí 2 : 1 — WCAG không áp quy tắc 3:1 cho phần trang trí Hai bề mặt kề nhau 1.12 : 1 — đủ để một tấm thẻ đọc ra là tách khỏi nền của nó","python3 addons/gohud/tools/check_contrast.py",-1],[1,"same-hue-text-on-a-same-hue-tint","Chữ cùng tông trên nền pha cùng tông",1,"Cái bẫy này xuất hiện ba lần trong chính mã nguồn này — nút đang bấm (tấm nền màu nhấn, nhãn màu nhấn), nút nguy hiểm, và chip. Nó trông đẹp trong một ô màu mẫu rồi sụp đổ ngay khi bị đo, vì hai bên chung một tông màu nên chẳng chênh nhau chút độ sáng nào. Vì vậy màu nhãn không được chọn bằng tay. Trình dựng theme và GoSkin mỗi bên đều đẩy độ sáng — và chỉ độ sáng thôi — cho tới khi vượt ngưỡng trên đúng tấm nền mà chữ thật sự nằm lên. Tông màu và độ bão hòa được giữ nguyên, nên bảng màu giữ được cá tính và đổi nó thì độ tương phản vẫn còn.","",44],[1,"colour-read-as-text-and-colour-painted-as-area-w","Màu đọc như chữ và màu tô như mảng muốn hai điều ngược nhau",1,"Trên theme sáng, màu cảnh báo phải tối đi mới đọc được khi làm chữ (#96500A). Khi phần tô của thanh kế thừa màu đó, thanh kinh nghiệm hóa nâu. Riêng màu thì không cứu được: vàng vốn dĩ đã sáng, nên nó vượt 3:1 dù rãnh chẳng xám chút nào, còn làm rãnh tối đi lại khiến mọi thứ tệ hơn (1.52 → 1.06). Nên hai thứ được tách ra. Màu thì giữ nguyên độ rực — bảng màu mang theo các màu chỉ dùng để tô như warning_vivid. Phần viền gánh lấy độ tương phản — GoSkin vẽ một đường viền 1dp lên bất kỳ phần tô nào không đạt nổi 3:1 so với rãnh của nó, để câu hỏi \"đầy đến đâu rồi\" vẫn đọc được. Bỏ sót thì sẽ bị báo. Thiếu một màu *_vivid, một phần tô ra quá tối sẽ khiến trình dựng in ra 막대가 칙칙하다 — 팔레트에 warning_vivid 를 더한다 (thanh trông xỉn màu — hãy thêm warning_vivid vào bảng màu). Một chỗ trước đây âm thầm xuống cấp thì nay lên tiếng.","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # đọc như chữ warning_vivid=hexc(\"F2A007\"), # tô lên thanh )",44],[1,"a-floating-panel-cannot-know-what-is-behind-it","Một tấm nền nổi không thể biết phía sau nó là gì",1,"HUD được vẽ đè lên game — một cánh đồng tuyết, hay một hang động. Nếu tấm nền của nó bán trong suốt, thứ nằm sau sẽ lộ qua và đổi luôn màu của tấm nền, kéo độ tương phản của chữ tụt theo. Ở mức đục 82%, chữ mờ nhạt của các theme tối rơi xuống 3.74:1 trên nền sáng — dưới mức tối thiểu. Nên các tấm nền bán trong suốt được đo với nền trắng tinh và nền đen tuyền phía sau; đó là những gì tệ nhất mà một cảnh game có thể bày ra. Tấm nền HUD của các theme kèm theo đủ đục để vượt ngưỡng (92%) mà vẫn giữ được vẻ trong như kính. Cũng vì lý do đó mà màu biểu tượng cũng không cố định. Hình vẽ trong ô nhanh từng bị gán cứng màu trắng và đo ra 1.11:1 trên một theme sáng — giờ nó đi theo tấm nền mà nó nằm lên, đúng như các nhãn chữ. Hai bộ kiểm tra, hai tầm với. check_contrast.py đọc các file theme; còn những màu mà một skin trộn ra lúc đang chạy (chip, ô nhanh) thì được đo trong mục skin contrast của bộ kiểm thử chạy bên trong Godot.","",44],[2,"surfaces","Cửa sổ nổi",0,"","",-1],[2,"gosurface-the-shell","GoSurface — lớp vỏ",1,"Popup, bảng trượt và danh sách thả xuống đều dùng chung cái này. Nó lo vùng an toàn, bàn phím ảo, đầu và chân trang cố định, thân cuộn được, cửa sổ nào đang ở trên cùng, việc trả focus về chỗ cũ, quyền sở hữu nút Back và thao tác kéo để đổi kích thước. Vị trí đặt Trông như Dùng cho CENTER Một tấm thẻ ở giữa Xác nhận, cài đặt BOTTOM Một bảng trồi lên từ dưới Danh sách, trang quản lý ANCHOR Một tấm thẻ ghim bên cạnh một control Danh sách thả xuống, menu ngữ cảnh Nó không tự gỡ mình đi. Phản ứng với close_requested — ẩn đi hay giải phóng — là việc của màn hình sở hữu nó, vì lớp vỏ không thể biết vì sao nó đang đóng (lưu rồi đóng, hay bỏ luôn).","",48],[2,"gosheet-a-page-from-the-bottom","GoSheet — một trang trồi lên từ đáy",1,"Nó sở hữu một CanvasLayer nên chắc chắn nằm trên HUD. open() dọn sạch phần thân và tắt nút Back cùng các hàng cố định — một cái nút chết trên màn hình không có chỗ nào để quay về thì người ta đọc ra là hỏng.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Túi đồ\") sheet.toolbar().add_child(GoStyle.line_edit(\"Tìm kiếm…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"Đóng\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",48],[2,"godialogs-confirmations-you-await","GoDialogs — hộp thoại xác nhận mà bạn await",1,"confirm(title, body, ok_text, cancel_text, extra, args, destructive) — mọi thứ sau phần thân đều tùy chọn, và alert() cũng vậy nhưng chỉ có một nút. Hãy đặt destructive cho thao tác không thể hoàn tác: nút xác nhận trở thành nút tô đặc GoStyle.Tone.DANGER_SOLID. Trên theme sáng, một nhãn nguy hiểm chỉ pha màu buộc phải tối đi đến mức đọc ra thành chữ đen; nút tô đặc thì giữ chữ trắng trên nền đỏ. Sắc thái được áp lại ở mỗi lần gọi vì chỉ một cửa sổ được tái sử dụng, và một lần confirm() thứ hai trong lúc cái trước còn mở sẽ trả về false ngay. confirm_key() nhận khóa dịch. Bố cục nút. action_layout mặc định là VERTICAL (an toàn cho những bản dịch dài), HORIZONTAL cho một hàng chia đôi bề ngang, hoặc AUTO — chỉ dùng một hàng khi cả hai nhãn vừa đúng nửa tấm thẻ trên một dòng, còn không thì xếp chồng. action_gap là khoảng cách giữa các nút và body_gap là khoảng trống phía trên chúng — hãy để nó rộng hơn khoảng cách giữa các nút để câu hỏi và lựa chọn đọc ra thành hai phần. Nếu chỉ muốn áp cho một hộp thoại, hãy gọi set_next_action_layout() trước khi mở nó. Hàng nút được dựng khi hộp thoại mở lần đầu, nên một GoDialogs nạp bằng autoload không thêm gì vào lúc khởi động.","if await dialogs.confirm(\"Xóa bản lưu\", \"Thao tác này không thể hoàn tác.\"): delete_save()",48],[2,"goform-a-width-capped-form","GoForm — biểu mẫu giới hạn bề ngang",1,"Nó bảo đảm mọi nhãn con cháu đều xuống dòng. Không có điều đó, một câu dài sẽ kéo thành một dòng duy nhất có bề rộng tối thiểu vượt quá màn hình, rồi hai bên bị cắt cụt — đến mức bạn không còn nhận ra mình đang ở màn hình nào. Bật xuống dòng bằng tay cho từng scene thì lần nào cũng quên.","",48],[2,"goscroll-touch-scrolling","GoScroll — cuộn bằng ngón tay",1,"Chỉ đặt một thứ vào bên trong. Phần đầu trang và hàng nút thì để bên ngoài — một danh sách dài không được phép đẩy chúng ra khỏi màn hình. use_panel_edge() dời thanh cuộn vào phần đệm sẵn có của tấm thẻ mà nội dung vẫn giữ nguyên lề thụt.","",48],[2,"messages","Nói cho người chơi biết một điều gì đó",0,"","",-1],[2,"gonotice-snackbar","GoNotice — snackbar",1,"Nó không bao giờ chặn thao tác. Một thông báo là để đọc chứ không phải để bấm. Nó không lấy focus, không chặn thao tác trong game, và cái nút nằm dưới nó vẫn bấm được. Khi cần xác nhận thì dùng GoDialogs; khi cần một lựa chọn thì dùng GoPromptCard.","",54],[2,"gopromptcard-a-question-that-does-not-block","GoPromptCard — câu hỏi không chặn game",1,"Nổi ở một bên và không có lớp phủ mờ. Game vẫn chạy tiếp.","",54],[2,"gocoachmark-guided-tour","GoCoachMark — chuyến tham quan có hướng dẫn",1,"Chỉ vào từng control thật một. Chỉ tấm thẻ mới nhận thao tác, nên bấm thẳng vào chính control đang được làm nổi là sang bước kế — \"bấm vào đây\" trở thành một hành động chứ không còn là một câu chữ. title và body có thể là khóa dịch hoặc chữ thường. Bước nào có mục tiêu đã biến mất thì được bỏ qua.","tour.start([ {\"target\": bag_button, \"title\": \"Túi\", \"body\": \"Mọi thứ bạn nhặt được đều nằm ở đây.\"}, {\"target\": map_button, \"title\": \"Bản đồ\", \"body\": \"Bấm để mở bản đồ đầy đủ.\"}, ])",54],[2,"hud","HUD",0,"","",-1],[2,"the-small-things-decide-whether-it-looks-good","Những thứ nhỏ mới quyết định nó có đẹp hay không",1,"Bạn có gọt giũa các tấm nền lớn đến đâu đi nữa — thứ đập vào mắt luôn là một chi tiết nhỏ: một từ bị cắt làm đôi, một vệt sáng bị xén mất, một cái ô chật chội. Bốn chuyện như vậy được chỉ ra vào 2026-09-13 và đã sửa ngay trong widget và theme, không sửa ở màn hình demo, nên mọi màn hình đều được kết quả như nhau. Hiện tượng Nguyên nhân Cách sửa Chữ Done trên coach mark thành Don/e Một cái nút đang bật xuống dòng sẽ trừ bề rộng chữ của nó khỏi bề rộng tối thiểu — bóp lại là nó gãy ngay giữa từ GoStyle.fit_words(): một từ thì không bao giờ xuống dòng; nhiều từ thì xuống dòng, nhưng từ dài nhất luôn vừa — xét trên chữ được hiển thị chứ không phải khóa dịch, và biểu mẫu áp lại khi đổi ngôn ngữ Vệt sáng của một nút rộng hết khung bị cắt dọc ở cạnh trái Một container cuộn thì cắt ở mép của nó, không có ngoại lệ. Chỉ bên phải sống sót, nhờ khoảng chừa cho thanh cuộn GoScroll mượn phần đệm của cha để đẩy mép của nó ra 12dp rồi trả lại vào trong — nội dung không xê dịch Thời gian, biểu tượng và số lượng xếp chồng theo chiều dọc trong một ô Ba hàng nhồi trong 48dp Biểu tượng to ở giữa, phím tắt góc trên bên trái, số lượng là một badge ở góc dưới bên phải, thời gian còn lại là một badge đè lên biểu tượng — tấm nền của badge lấy từ badge_box() của skin Một danh sách thả xuống phẳng lì, không thấy mục nào đang chọn Mục đang rê chuột dùng tấm nền của nút; dấu chọn tròn là mặc định nhợt nhạt của engine Một tấm nền rê chuột riêng (pha nhẹ màu nhấn), dấu chọn tròn vẽ giống hộp kiểm, chiều cao mỗi mục đủ cho ngón tay Danh sách thả xuống — tấm nền rê chuột và dấu chọn tròn Ô nhanh — badge ở góc và thời gian còn lại (sci-fi) Hãy cho những nút chỉ có biểu tượng một lời mô tả bằng GoStyle.icon_button(icon, action, -1, tooltip_key) — tooltip cho người dùng chuột và tên dành cho trình đọc màn hình đều lấy từ đúng một giá trị đó. gohud tự vẽ tooltip: bản mặc định của engine cắt chữ thành mỗi dòng một ký tự khi phép tính bề rộng của nó sai (đo được là rộng 1dp). Thẻ coach mark biết tránh các vật cố định Khi màn hình nằm ngang, tấm thẻ trước đây bị đẩy ra sát mép trên hoặc mép dưới — đúng chỗ phần đầu trang và các mảnh HUD ngồi; trong bản demo nó đè lên cụm → × của đầu trang. Giờ nó giữ ngang tầm với mục tiêu, bước tránh mọi GoHudAnchor có giữ chỗ, và nhận thêm những thứ khác cần né qua keep_clear. Nó dịch đi quãng ngắn nhất đủ thoát vật cản mà không che mất mục tiêu, và đứng yên khi màn hình quá nhỏ để né hết — chồng lên nhau vẫn hơn biến mất. Chiều sâu của nó — để đọc ra là nổi trên trang — đến từ các núm chỉnh của skin (float_shadow_size, float_shadow_lift, float_shadow_alpha; skin vát góc thì dùng float_glow_size).","tour.keep_clear = [header_bar, toolbar] # các vật cố định không phải là anchor",58],[2,"screens-with-a-mouse-and-a-keyboard","Màn hình có chuột và bàn phím",1,"Ngón tay thì không có trạng thái rê chuột. Chỉ làm cho di động thôi là hai trạng thái riêng của máy để bàn chẳng ai kiểm — và một trong hai đã hỏng: vòng focus của gohud vô hình trên nút chính. Tấm nền mang màu nhấn còn vòng focus cũng vậy: 1.00:1, cùng một màu vẽ chồng lên chính nó. Di chuyển bằng bàn phím thì không cách nào biết mình đang ở đâu. Từ trên xuống: bình thường · rê chuột · focus. Nút tô đặc nhận một vòng focus tương phản với tấm nền của nó. Nút tô đặc (GoPrimaryButton, GoDangerSolidButton) dùng một vòng focus tương phản với chính tấm nền của nó — tối trên theme tối, trắng trên theme sáng, một khung ngắm góc tối ở bản sci-fi. Bộ kiểm tra tương phản đo vòng focus so với tấm nền nó nằm lên, nên quy tắc này sống sót qua một lần đổi bảng màu (WCAG 2.4.11 yêu cầu 3:1 cho chỉ báo focus).","",58],[2,"gohudanchor-nine-spots","GoHudAnchor — chín vị trí",1,"Tôn trọng vùng an toàn và lề mép màn hình. Cho nó một landscape_spot thì nó đổi chỗ khi màn hình nằm ngang — những control nằm giữa đáy lúc màn hình dọc có thể dời sang góc dưới bên phải. Vì sao có nó. Viết tay cho từng mảnh HUD thì anchor và offset sẽ lệch dần: thanh máu chui xuống dưới lỗ khoét camera trên máy có tai thỏ, còn một nút điều khiển thì rơi vào thanh cử chỉ khi màn hình nằm ngang. Phép tính đó nằm gọn ở một chỗ. Giữ cho nội dung không chui xuống dưới HUD Khi một màn hình cuộn được phải chia màn hình với HUD, nội dung trượt xuống bên dưới nó và hai lớp chữ chồng lên nhau đến mức chẳng đọc nổi bên nào. Chuyện đó đã xảy ra hai lần trong add-on này: chữ gợi ý của một ô nhập bị kẹt giữa các ô nhanh, và núm của một công tắc trong phần cài đặt rơi trúng thanh máu. Mỗi hình chữ nhật được né theo hướng tốn ít diện tích nhất. Một thanh ở góc trên bên phải thì được bước tránh xuống dưới trên điện thoại dọc (13% chiều cao) và sang ngang khi nằm ngang (21% chiều rộng) — né nó theo chiều dọc lúc nằm ngang sẽ tốn 27% màn hình. Phần đất đã nhường rồi thì được trừ ra trước khi đo tới hình chữ nhật kế tiếp. Các mảnh HUD cũng va vào nhau Chín vị trí chia màn hình ra; chúng không bảo đảm các mảnh không đụng nhau. Một snackbar rộng ở giữa mép trên đã đáp thẳng lên thanh máu ở góc trên bên phải, che mất con số — bạn không đọc nổi mình còn bao nhiêu máu. Nó chỉ bước tránh theo chiều dọc — dịch cả sang ngang nữa thì một thông báo canh giữa sẽ hiện ra ở một chỗ khác nhau mỗi lần. Và nó chỉ né những mảnh không tự bước tránh: nếu cả hai cùng nhường, hai bên sẽ đổi chỗ cho nhau mãi mãi.","form.avoid_hud = true # tránh mọi GoHudAnchor đang hiện joystick_anchor.reserve_space = false # …trừ những cái chỉ hiện ra dưới ngón tay notice_anchor.avoid_peers = true # nằm xuống dưới HUD cố định notice_anchor.reserve_space = false # và không đẩy trang trong lúc nó đang hiện",58],[2,"gobar-health-mana-experience","GoBar — máu, mana, kinh nghiệm",1,"Thay đổi chạy mượt trong 0,18 giây — một thanh máu nhảy phắt một cái thì không cho bạn biết cú đánh vừa rồi nặng đến đâu. reduce_motion làm nó đổi tức thì. Số lớn được rút gọn thành 12.3k để bề rộng của thanh không giật lên giật xuống theo số chữ số.","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # token chỉ dùng để tô hp.set_values(320, 500) # \"320 / 500\"",58],[2,"goslot-one-quick-slot","GoSlot — một ô nhanh",1,"Biểu tượng, số lượng, hồi chiêu và phím tắt trên cùng một mặt. Treo badge lủng lẳng quanh một vòng tròn nhỏ sẽ làm mỗi ô một bề rộng khác nhau và cả hàng lắc lư. Cỡ nhìn thấy và cỡ chạm là hai thứ khác nhau. Các ô xếp sát nhau có vùng chạm 48dp chồng lên nhau; phần chồng lấn thuộc về ô nào có tâm gần hơn — hãy cho chúng biết về nhau qua touch_peers. keyboard_focus mặc định tắt, nên một hàng tám ô nhanh không chen giữa người dùng bàn phím và mọi control cài đặt trong thứ tự Tab. Hãy bật nó khi bàn phím hoặc tay cầm là cách nhập liệu duy nhất.","",58],[2,"gojoystick-virtual-stick","GoJoystick — cần điều khiển ảo",1,"Chế độ Hành vi FIXED Luôn ở đúng một chỗ — dễ tìm mà không cần nhìn FOLLOW Hiện ra ngay nơi ngón cái chạm xuống RELATIVE Sau khi hiện ra thì tiếp tục đi theo ngón cái — thoải mái cho những đoạn di chuyển dài Vector2 mà tín hiệu moved trả về có độ dài từ 0 đến 1, nên bạn nhân thẳng nó vào tốc độ được; nó không đổi theo kích thước màn hình hay DPI.","",58],[2,"goiconbutton-looks-small-presses-large","GoIconButton — trông nhỏ, bấm rộng",1,"Chỉ an toàn khi các nút bên cạnh bỏ qua thao tác. Nếu vùng đã nới rộng phủ lên nút kế bên, nút đó sẽ không còn phản hồi. Các nút biểu tượng đặt sát nhau cần touch_peers.","",58],[2,"factory","GoStyle — một chỗ duy nhất để tạo ra mọi thứ",0,"Gọi thẳng Button.new() thì phần đệm, chiều cao và cách xuống dòng sẽ lệch nhau chút ít giữa các màn hình. Chỗ lệch đó vô hình khi review code và lộ rõ trong một tấm ảnh chụp màn hình. Nhóm Hàm Cấu trúc column row wrap_row padding spacer divider responsive_grid aspect foldable Văn bản label label_key line section typography Nút button button_key icon_button list_button list_row apply_icon style_choice_card style_chip_button style_chip_label Nhập liệu line_edit textarea toggle checkbox slider picker select dropdown radio_group segmented choice_grid Hiển thị card chip hud_panel chip_panel avatar skeleton alert table tabs breadcrumb progress empty_state Mảnh của lớp nổi surface box floating disc face_padding Tiện ích form fit_words natural_width tooltip_node card_body let_input_through box() luôn trả về một StyleBoxFlat, vì phía gọi nhận nó rồi chỉnh bg_color hoặc corner_radius. Hãy dùng surface() khi cần giữ nguyên một hình dáng tùy biến.","",-1],[2,"list-rows-with-a-description","Hàng danh sách có dòng mô tả",1,"Một hàng có dòng thứ hai được cấp phần đệm trên và dưới bằng nhau, rộng rãi hơn hàng một dòng, và cặp tiêu đề/mô tả luôn canh giữa theo chiều dọc bên cạnh biểu tượng — kể cả khi một container kéo hàng đó cao lên, và cả sau khi dòng mô tả xuống thành nhiều dòng. Cả hàng vẫn là một vùng chạm duy nhất. Hàng hai dòng, ô nhanh và các thanh trong ví dụ trung cổ — vẫn những lệnh gọi factory đó dưới medieval_light.","GoStyle.list_button(GoIconSet.SWORD, \"Kiếm Thề Nguyện\", _inspect, Color.TRANSPARENT, \"Trường kiếm / Tấn công 42\", false)",66],[2,"flowing-rows","Hàng tự xuống dòng",1,"Hãy đặt các control vào wrap_row ở bề rộng tự nhiên của chúng. Nếu cứ để bật xuống dòng, bề rộng tối thiểu của một cái nút tụt xuống gần như bằng không và hàng lấy đó làm cỡ ô — nhãn co lại thành mỗi dòng một ký tự. Factory ngăn chuyện này giúp bạn.","",66],[2,"never-leave-an-empty-list-empty","Đừng bao giờ để một danh sách rỗng trống trơn",1,"Người ta đọc một màn hình trắng trơn ra là hỏng.","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"Chưa có gì ở đây\"))",66],[2,"hooks","Hook để kế thừa",0,"Mọi chỗ dựng ra một widget con đều đi qua một phương thức ghi đè được, nên một dự án có kế thừa các kiểu của gohud sẽ đưa được lớp con của mình vào bên trong các widget mà không phải chép code. Hook Widget Mặc định _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark Ẩn tấm thẻ trong lúc một cửa sổ modal đang mở","",-1]]};
